 function blocks(options){const l=words(options.language),lang=options.language;const b=[{text:'DIOPONG PRIMARY SCHOOL',kind:'school'},{text:`${l.grade} ${options.grade}: ${options.answers?l.answers:l.worksheet}`,kind:'title'},{text:options.topicLabel|| (lang==='nso'?'Dihlogo tše di kgethilwego':'Selected learning activities'),kind:'subtitle'},{text:l.note,kind:'note'}];if(!options.answers)b.push({text:`${l.name}: ____________________    ${l.date}: ______________`,kind:'body'});options.items.forEach((a,i)=>{b.push({text:`${i+1}. ${a.title[lang]}`,kind:'heading'},{text:a.task[lang],kind:'body'});if(options.answers)b.push({text:`${l.answer}: ${a.answer[lang]}`,kind:'answer'});else b.push({text:'',kind:'space'});});return b;}
